sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?person ?deathDate WHERE {
  VALUES ?person { dbr:Alicia_Little dbr:Christopher_Addison,_1st_Viscount_Addison }

  OPTIONAL { ?person dbp:deathDate ?dbpDate . }
  OPTIONAL { ?person dbo:deathDate ?dboDate . }

  BIND( COALESCE(?dbpDate, ?dboDate) AS ?deathDate )
}
LIMIT 100

